"""Summarize node channel gaps without modifying the node."""
import json
from pathlib import Path
import re
import stat
import sys


CHANNELS = ("obs", "must")


def reject_constant(value):
    raise ValueError("non-JSON constant: " + value)


def read_json(data):
    return json.loads(data.decode("utf-8"), parse_constant=reject_constant)


def channel_files(node, channel):
    pattern = re.compile(re.escape(channel) + r"\.([0-9]{12})\.jsonl")
    numbered = []
    active = None
    for path in node.iterdir():
        match = pattern.fullmatch(path.name)
        if match is None and path.name != channel + ".active.jsonl":
            continue
        if not stat.S_ISREG(path.stat(follow_symlinks=False).st_mode):
            continue
        if match is None:
            active = path
        else:
            numbered.append((int(match.group(1)), path))
    result = [path for _, path in sorted(numbered)]
    if active is not None:
        result.append(active)
    return result


def read_channel(node, channel, bad):
    counts = {}
    for path in channel_files(node, channel):
        parts = path.read_bytes().split(b"\n")
        for line_number, line in enumerate(parts[:-1], 1):
            try:
                record = read_json(line)
            except (UnicodeError, ValueError):
                bad.append({"file": path.name, "line": line_number, "why": "bad_json"})
                continue
            if not isinstance(record, dict) or type(record.get("seq")) is not int or record["seq"] < 1:
                bad.append({"file": path.name, "line": line_number, "why": "no_seq"})
                continue
            seq = record["seq"]
            counts[seq] = counts.get(seq, 0) + 1
        if parts[-1]:
            bad.append({"file": path.name, "line": len(parts), "why": "torn"})
    return counts


def read_state(node):
    path = node / "state.json"
    if not path.exists() and not path.is_symlink():
        return {}, False
    try:
        state = read_json(path.read_bytes())
    except (OSError, UnicodeError, ValueError):
        return {}, True
    if not isinstance(state, dict) or not isinstance(state.get("channels"), dict):
        return {}, True
    valid = {}
    invalid = False
    for channel in CHANNELS:
        fields = state["channels"].get(channel)
        if (not isinstance(fields, dict)
                or type(fields.get("next_seq")) is not int
                or (channel == "must" and type(fields.get("acked_upto")) is not int)):
            invalid = True
        else:
            valid[channel] = fields
    return valid, invalid


def summarize(node):
    bad = []
    records = {channel: read_channel(node, channel, bad) for channel in CHANNELS}
    state, invalid_state = read_state(node)
    if invalid_state:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    channels = {}
    for channel in CHANNELS:
        counts = records[channel]
        seqs = sorted(counts)
        first = seqs[0] if seqs else None
        last = seqs[-1] if seqs else None
        fields = state.get(channel)
        channels[channel] = {
            "count": sum(counts.values()),
            "first": first,
            "last": last,
            "missing": [[a + 1, b - 1] for a, b in zip(seqs, seqs[1:]) if b > a + 1],
            "dup": [seq for seq in seqs if counts[seq] >= 2],
            "next_seq": fields["next_seq"] if fields is not None else None,
            "unacked": (sum(seq > fields["acked_upto"] for seq in seqs)
                        if fields is not None and channel == "must" else None),
            "stale_next": (fields["next_seq"] != last + 1
                           if fields is not None and last is not None else None),
        }
    bad.sort(key=lambda item: (item["file"], item["line"] if item["line"] is not None else 0, item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1:
        return 2
    node = Path(args[0])
    if not node.is_dir():
        return 2
    try:
        result = summarize(node)
    except OSError:
        return 2
    print(json.dumps(result, ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
